<?php $user=sc_user();if(!$user){echo '<section class="sc-store"><h1>Your orders</h1><a class="sc-buy" href="'.sc_url('signin').'">Please log in</a></section>';return;}$orders=sc_query('SELECT * FROM web_orders WHERE online_user_id=? ORDER BY id DESC LIMIT 50','i',[$user['id']])->get_result(); ?>
<section class="sc-store"><span class="sc-kicker">YOUR STEPCURE</span><h1>Your orders.</h1><?php sc_flash(); ?><?php if(!$orders->num_rows): ?><p>No orders yet. <a href="<?= sc_url('products') ?>">Explore the collection</a></p><?php endif; ?><?php while($order=$orders->fetch_assoc()): $delivery=json_decode($order['delivery'],true);$lines=sc_query('SELECT * FROM web_order_items WHERE order_id=?','i',[$order['id']])->get_result(); ?><article class="sc-panel sc-order"><h2><?= sc_e($order['order_number']) ?></h2><p><?= sc_e($order['created_at']) ?> · <?= sc_e(ucfirst($order['status'])) ?> · Cash on delivery · <?= sc_e($order['payment_status']) ?></p><?php while($line=$lines->fetch_assoc()): ?><p><?= sc_e($line['product_name']) ?> × <?= (int)$line['quantity'] ?> <strong><?= sc_money((int)round($line['line_total']*100)) ?></strong></p><?php endwhile; ?><hr><p>Tax <?= sc_money((int)round($order['tax']*100)) ?> · Shipping ₹0.00</p><p><strong>Total <?= sc_money((int)round($order['total']*100)) ?></strong></p><p>Deliver to <?= sc_e($delivery['full_name']) ?>, <?= sc_e($delivery['address']) ?>, <?= sc_e($delivery['city']) ?>, <?= sc_e($delivery['state']) ?> <?= sc_e($delivery['pin']) ?></p></article><?php endwhile; ?><a href="<?= sc_url('account') ?>">Back to account</a></section>
